const ALIASES: Record<string, string> = {
  moonshot: 'moonshotai',
  deepseek_ai: 'deepseek',
  'x-ai': 'xai',
  'meta-llama': 'meta',
}

const MONOGRAM: Record<string, { bg: string; fg: string }> = {
  cohere: { bg: '#fae8ff', fg: '#c026d3' },
  groq: { bg: '#fce7f3', fg: '#db2777' },
  cerebras: { bg: '#ccfbf1', fg: '#0d9488' },
  zai: { bg: '#ede9fe', fg: '#7c3aed' },
  'z-ai': { bg: '#ede9fe', fg: '#7c3aed' },
  tuner: { bg: '#dbeafe', fg: '#2563eb' },
}

export interface ProviderLogoProps {
  provider?: string
  size?: number
}

/** Real brand mark when we have one; tinted monogram otherwise. */
export function ProviderLogo({ provider, size = 16 }: ProviderLogoProps): ReactNode {
  const key = ALIASES[provider ?? ''] ?? provider ?? ''
  const logo = LOGOS[key]
  if (logo) {
    return (
      <svg width={size} height={size} viewBox={logo.viewBox} role="img" aria-label={key}>
        {logo.paths.map((d, i) => (
          <path key={i} d={d} fill={logo.fill} />
        ))}
      </svg>
    )
  }
  // Unknown providers fall back to a neutral monogram drawn from theme tokens
  // (secondary tile, muted glyph) — the previous hardcoded grays (#f3f4f6 /
  // #6b7280) were tuned for light mode and read as a washed-out hole on dark.
  // `style` rather than the `fill` attribute so the var() references resolve.
  const mono = MONOGRAM[key]
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" role="img" aria-label={key || 'model'}>
      <rect width="16" height="16" rx="4" style={{ fill: mono ? mono.bg : 'hsl(var(--secondary))' }} />
      <text x="8" y="11.6" textAnchor="middle" style={{ fill: mono ? mono.fg : 'hsl(var(--muted-foreground))' }} fontSize="9" fontWeight="700" fontFamily="system-ui, sans-serif">
        {(key || '?').charAt(0).toUpperCase()}
      </text>
    </svg>
  )
}
